const url = $json["DOCS URL"];
if (!url) throw new Error("DOCS URL missing");

const match = String(url).match(/\/document\/d\/([^\/\?]+)/);
if (!match) throw new Error("Could not extract document ID");

return {
  json: {
    ...$json,
    docId: match[1],
  },
};

function readText(el) {
  return el?.textRun?.content ?? '';
}

const out = [];

for (const item of $input.all()) {
  const title = item.json.title ?? '';
  const doc = item.json.body;
  const blocks = [];

  const content = doc?.content ?? [];
  for (const c of content) {
    const p = c.paragraph;
    if (!p) continue;

    const text = (p.elements ?? []).map(readText).join('').trim();
    if (!text) continue;

    const style = p.paragraphStyle?.namedStyleType;
    const type =
      style === 'HEADING_1' ? 'h1' :
      style === 'HEADING_2' ? 'h2' :
      style === 'HEADING_3' ? 'h3' : 'p';

    blocks.push({ type, content: text });
  }

  const h1Block = blocks.find(b => b.type === 'h1');
  const rawTitle = h1Block ? h1Block.content : (title || 'Untitled');
  const finalTitle = rawTitle.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());

  out.push({
    json: {
      ...item.json,
      title: finalTitle,
      blocks,
    },
  });
}

return out;

function titleCase(str = '') {
  return str
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function escapeHtml(s = '') {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function splitIntoSentences(text = '') {
  const input = String(text).replace(/\s+/g, ' ').trim();
  if (!input) return [];

  if (typeof Intl !== 'undefined' && Intl.Segmenter) {
    const seg = new Intl.Segmenter('en', { granularity: 'sentence' });
    return Array.from(seg.segment(input))
      .map(s => s.segment.trim())
      .filter(Boolean);
  }

  const DOT = '\u222f';
  const NON_TERMINAL_ABBR = [
    'Mr','Mrs','Ms','Dr','Prof','Sr','Jr','St','Mt','Capt','Lt','Col','Gen','Sgt','Rev','Hon',
    'Gov','Sen','Rep','Pres','No','Fig','Dept','Univ','Inc','Ltd','Co','Corp',
    'vs','etc','e.g','i.e',
    'Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Sept','Oct','Nov','Dec'
  ];

  let t = input;

  for (const a of NON_TERMINAL_ABBR) {
    const pattern = a.replace(/\./g, '\\.');
    const re = new RegExp(`\\b${pattern}\\.`, 'gi');
    t = t.replace(re, (m) => m.replace(/\./g, DOT));
  }

  t = t.replace(/\b((?:[A-Za-z]\.){2,}[A-Za-z])\./g, (_, g1) => g1.replace(/\./g, DOT) + '.');
  t = t.replace(/(\d)\.(\d)/g, `$1${DOT}$2`);

  const parts = t.match(/.*?(?:[.!?]+(?:["'\"\)\\]]+)?(?=\s|$)|$)/g) || [];
  return parts
    .map(s => s.trim())
    .filter(Boolean)
    .map(s => s.replaceAll(DOT, '.'));
}

function removeToLearnMoreSentences(sentences) {
  return sentences.filter(s => !/to learn more/i.test(s));
}

if (!Array.isArray($json.blocks)) {
  throw new Error('Missing json.blocks from previous node.');
}

const rawTitle = $json.title || 'Untitled';
const title = titleCase(rawTitle);
const blocks = $json.blocks;

let html = '';

for (const block of blocks) {
  if (!block || !block.type) continue;

  if (block.type === 'h1') {
    continue;
  }

  if (block.type === 'h2') {
    const h2 = escapeHtml(block.content || '');
    const h2Raw = block.content || '';

    html += `<!-- wp:heading -->\n`;
    html += `<h2 class="wp-block-heading">${h2}</h2>\n`;
    html += `<!-- /wp:heading -->\n\n`;

    html += `<!-- wp:html -->\n`;
    html += `<!-- UNSPLASH:START:${h2Raw} -->\n`;
    html += `<figure class="wp-block-image aligncenter size-full">`;
    html += `<img src="https://placehold.co/1200x700/e2e8f0/64748b?text=${encodeURIComponent(h2Raw)}" alt="${h2}" style="width:100%;height:auto;" />`;
    html += `<figcaption class="wp-element-caption">Loading image...</figcaption>`;
    html += `</figure>\n`;
    html += `<!-- UNSPLASH:END:${h2Raw} -->\n`;
    html += `<!-- /wp:html -->\n\n`;

    continue;
  }

  if (block.type === 'p') {
    let sentences = splitIntoSentences(block.content || '');
    sentences = removeToLearnMoreSentences(sentences);

    for (let i = 0; i < sentences.length; i += 2) {
      const group = sentences.slice(i, i + 2).join(' ').trim();
      if (!group) continue;

      const p = escapeHtml(group);

      html += `<!-- wp:paragraph -->\n`;
      html += `<p>${p}</p>\n`;
      html += `<!-- /wp:paragraph -->\n\n`;
    }
  }
}


return { json: { ...$json, html } };

// Extract UNSPLASH markers AND section content from the draft post
// Reads the paragraphs under each heading for smarter image search
const results = [];

for (const item of $input.all()) {
  const content = item.json.content?.raw || item.json.content?.rendered || '';
  const postId = String(item.json.id);
  const postTitle = item.json.title?.rendered || item.json.title?.raw || 'Untitled';

  // Extract section content per heading (text between h2 tags)
  const sections = {};
  const sectionRegex = /<h2[^>]*>(.*?)<\/h2>([\s\S]*?)(?=<h2|$)/g;
  let secMatch;
  while ((secMatch = sectionRegex.exec(content)) !== null) {
    const hText = secMatch[1].replace(/<[^>]*>/g, '').trim();
    const body = secMatch[2]
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]*>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (hText) sections[hText] = body;
  }

  const markerRegex = /<!-- UNSPLASH:START:(.*?) -->/g;
  const headers = [];
  let match;

  while ((match = markerRegex.exec(content)) !== null) {
    const headerText = match[1].trim();
    if (headerText) {
      headers.push(headerText);
    }
  }

  if (headers.length === 0) {
    console.log('No UNSPLASH markers found in post ' + postId);
    continue;
  }

  console.log(`Post ${postId}: Found ${headers.length} image slots`);

  for (const heading of headers) {
    const sectionContent = sections[heading] || '';
    console.log(`  ${heading}: ${sectionContent.length} chars of section content`);
    results.push({
      json: {
        postId,
        postTitle,
        postContent: content,
        heading,
        sectionContent,
        searchQuery: heading
      }
    });
  }
}

if (results.length === 0) {
  throw new Error('No UNSPLASH markers found in any post.');
}

return results;

// GENERATE SEARCH QUERIES
// Strict priority cascade: CATEGORY → TITLE → HEADING → SECTION CONTENT
// Category sets visual style, title extracts food subject,
// heading is the specific anchor, section content adds detail keywords

const results = [];

const STOP_WORDS = new Set([
  'the','a','an','and','or','but','in','on','at','to','for','of','with',
  'is','are','was','were','be','been','have','has','had','will','would',
  'can','could','when','where','who','what','how','why','which','their',
  'there','its','it','from','about','into','through','before','after',
  'above','below','between','under','since','without','best','top',
  'guide','tips','things','must','should','you','your','also','just',
  'even','very','really','much','many','some','any','all','each','every',
  'both','few','more','most','other','such','than','too','only','own',
  'same','so','not','no','nor','do','does','did','here','then','now',
  'out','up','down','off','over','well','back','still','way','may','get',
  'make','take','come','look','see','know','think','want','need','find',
  'like','time','people','day','good','new','first','last','long','great',
  'little','right','big','high','old','small','large','next','early',
  'while','around','another','going','keep','set','never','point',
  'worth','crossing','city','soups','dishes','foods','recipes','types',
  'kinds','ways','reasons','things','facts','secrets','ideas','options',
  'choices','picks','favorites','classics','versions','styles','places',
  'spots','examples','list','ultimate','complete','simple','easy',
  'popular','famous','world','global','international','regional','local'
]);

// LAYER 1: Category → visual style + image tone
function resolveCategory(rawCategory, postTitle) {
  const cat = (rawCategory || '').trim().toLowerCase();
  if (cat.includes('soup') || cat.includes('stew')) return 'soups_stews';
  if (cat.includes('pantry') || cat.includes('storage')) return 'pantry_storage';
  if (cat.includes('history')) return 'food_history';
  if (cat.includes('kitchen') || cat.includes('tip')) return 'kitchen_tips';
  if (cat.includes('recipe')) return 'recipes';
  // Fallback to title if category column is empty
  const t = (postTitle || '').toLowerCase();
  if (/(soup|stew|broth|bisque|chowder|sinigang|pozole|ramen|pho|bouillabaisse)/.test(t)) return 'soups_stews';
  if (/(pantry|storage|preserve|jar|shelf|freezer|store|keeping|keep)/.test(t)) return 'pantry_storage';
  if (/(history|origin|ancient|traditional|century|invented|first|oldest|began)/.test(t)) return 'food_history';
  if (/(tip|trick|hack|save money|kitchen|habit|mistake|avoid|skill|tool)/.test(t)) return 'kitchen_tips';
  return 'recipes';
}

// Visual style per category — appended to queries
const CATEGORY_VISUAL = {
  soups_stews:    { primary: 'bowl steam overhead',       secondary: 'warm bowl food',        fallback: 'soup food'         },
  pantry_storage: { primary: 'jar shelf organized',       secondary: 'storage kitchen pantry', fallback: 'pantry food'       },
  food_history:   { primary: 'rustic vintage traditional',secondary: 'heritage classic wooden', fallback: 'traditional food'  },
  kitchen_tips:   { primary: 'kitchen preparation close up', secondary: 'cooking technique',   fallback: 'kitchen food'      },
  recipes:        { primary: 'plated overhead food photography', secondary: 'dish close up fresh', fallback: 'food dish'     }
};

// LAYER 2: Title → food subject (what kind of food is this article about)
function extractFoodSubjectFromTitle(postTitle) {
  const t = (postTitle || '').toLowerCase();
  const subjectMap = [
    [/(soup|soups|broth|bisque|chowder|consomm|bouillabaisse|gazpacho|borscht|sinigang|pozole|pho|ramen|laksa|minestrone|goulash)/, 'soup'],
    [/(stew|stews|braise|braised|tagine|cassoulet|hotpot|pot roast)/, 'stew'],
    [/(noodle|noodles|pasta|spaghetti|fettuccine|udon|soba|pad thai|lo mein|vermicelli)/, 'noodle'],
    [/(rice|biryani|risotto|paella|congee|porridge|pilaf|fried rice)/, 'rice'],
    [/(bread|loaf|baguette|croissant|sourdough|focaccia|pastry|bun|roll)/, 'bread'],
    [/(breakfast|brunch|egg|bacon|pancake|waffle|omelette|oatmeal)/, 'breakfast'],
    [/(burger|sandwich|wrap|taco|burrito|hotdog|sub)/, 'sandwich'],
    [/(cake|dessert|pie|tart|cookie|brownie|chocolate|pudding|ice cream|donut|sweet)/, 'dessert'],
    [/(curry|curries|masala|korma|tikka|dal|vindaloo)/, 'curry'],
    [/(salad|slaw|greens|caesar|caprese)/, 'salad'],
    [/(seafood|fish|shrimp|crab|lobster|oyster|salmon|tuna|clam|mussel|squid)/, 'seafood'],
    [/(steak|beef|pork|chicken|lamb|roast|grill|bbq|barbecue|ribs|brisket)/, 'meat'],
    [/(pizza|flatbread|calzone)/, 'pizza'],
    [/(dumpling|gyoza|pierogi|empanada|samosa|dim sum|bao|wonton)/, 'dumpling'],
    [/(kimchi|pickle|ferment|sauerkraut|miso|kombucha|preserve)/, 'fermented food'],
    [/(cocktail|drink|smoothie|juice|coffee|tea|beverage)/, 'drink'],
    [/(jar|pantry|spice|herb|storage|shelf|freezer|ingredient)/, 'pantry ingredient'],
    [/(knife|cutting|tool|technique|skill|chop|dice|mince|prep)/, 'kitchen preparation'],
  ];
  for (const [pattern, subject] of subjectMap) {
    if (pattern.test(t)) return subject;
  }
  // Extract first meaningful noun from title after stripping number
  const words = (postTitle || '').replace(/^\d+\s+/, '').toLowerCase().split(/\s+/);
  const meaningful = words.find(w => w.length > 3 && !STOP_WORDS.has(w));
  return meaningful || 'food';
}

// LAYER 3: Heading → specific dish/subject for this image slot
function extractSubjectFromHeading(heading) {
  return heading
    .replace(/\s*\([^)]*\)/g, '')  // strip parentheticals
    .replace(/,.*$/, '')              // strip after comma
    .trim();
}

// LAYER 4: Section content → contextual detail keywords
function extractSectionKeywords(sectionContent) {
  return (sectionContent || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3 && !STOP_WORDS.has(w))
    .slice(0, 3);
}

for (const item of $input.all()) {
  const rawCategory  = item.json['CATEGORY'] || item.json.category || '';
  const postTitle    = item.json.postTitle || '';
  const heading      = item.json.heading || '';
  const sectionContent = item.json.sectionContent || '';

  // LAYER 1: category
  const articleCategory = resolveCategory(rawCategory, postTitle);
  const visual = CATEGORY_VISUAL[articleCategory];

  // LAYER 2: food subject from title
  const titleSubject = extractFoodSubjectFromTitle(postTitle);

  // LAYER 3: specific subject from heading
  const headingSubject = extractSubjectFromHeading(heading);

  // LAYER 4: detail keywords from section content
  const sectionKeywords = extractSectionKeywords(sectionContent);
  const sectionHint = sectionKeywords[0] || '';

  // Build 3 queries: most specific → broader → broadest fallback
  const q1 = `${headingSubject} ${visual.primary}`.trim();
  const q2 = `${titleSubject} ${headingSubject} ${visual.secondary}`.trim();
  const q3 = `${titleSubject} ${sectionHint} ${visual.fallback}`.trim().replace(/\s+/g, ' ');

  const queries = [q1, q2, q3]
    .map(q => q.trim())
    .filter((q, i, arr) => q && arr.indexOf(q) === i);

  console.log(`[${articleCategory}] "${heading}"`);
  console.log(`  Layer2 subject: "${titleSubject}" | Layer3: "${headingSubject}" | Layer4: "${sectionHint}"`);
  console.log(`  Q1: ${q1}`);
  console.log(`  Q2: ${q2}`);
  console.log(`  Q3: ${q3}`);

  for (let i = 0; i < queries.length; i++) {
    results.push({
      json: {
        ...item.json,
        searchQuery: queries[i],
        queryType: i === 0 ? 'primary' : 'fallback',
        queryIndex: i,
        articleCategory,
        categoryVisual: visual,
        _headingKey: item.json.postId + '|||' + heading
      }
    });
  }
}

return results;

// GROUP ALL SEARCH RESULTS BY HEADING
// Each input item carries _headingKey + photos[] already normalized + tagged with source
// No positional indexing needed — just group by _headingKey

const FOOD_POSITIVE = [
  'food','dish','meal','plate','bowl','soup','cook','kitchen','recipe',
  'eat','dining','cuisine','restaurant','ingredient','spice',
  'noodle','rice','bread','meat','fish','vegetable','fruit','dessert',
  'breakfast','lunch','dinner','broth','stew','curry','salad',
  'pasta','seafood','grill','bake','roast','fry','steam','sauce',
  'close up','overhead','flat lay','wooden','white background'
];

const FOOD_NEGATIVE = [
  'people','person','man','woman','men','women','portrait','face',
  'street','city','building','architecture','car','road',
  'crowd','tourist','travel','landscape','mountain','beach',
  'temple','church','flag','worker','sitting','standing','walking',
  'market stall','shop front','vendor'
];

function scoreFoodRelevance(photo, heading) {
  const text = [
    photo.alt_description || '',
    photo.description || '',
    Array.isArray(photo._tags) ? photo._tags.join(' ') : (photo._tags || '')
  ].join(' ').toLowerCase();

  let score = 0;

  // Food keyword bonus
  for (const w of FOOD_POSITIVE) if (text.includes(w)) score += 3;
  // Non-food penalty
  for (const w of FOOD_NEGATIVE) if (text.includes(w)) score -= 8;

  // Heading keyword match — strip parentheticals first
  const cleanHeading = heading.replace(/\s*\([^)]*\)/g, '').toLowerCase();
  const stopWords = new Set(['the','a','an','and','or','in','on','at','to','for','of','with','is','are']);
  const keywords = cleanHeading.split(/\W+/).filter(w => w.length > 2 && !stopWords.has(w));
  for (const kw of keywords) {
    if (text.includes(kw)) score += 4;
  }

  if ((photo.width || 1) > (photo.height || 1)) score += 1;

  return score;
}

// Group by _headingKey
const headingMap = new Map();

for (const item of $input.all()) {
  const key = item.json._headingKey;
  const photos = item.json.photos || [];
  const source = item.json._source || 'unknown';

  if (!key) continue;

  if (!headingMap.has(key)) {
    headingMap.set(key, {
      heading: item.json.heading,
      postId: item.json.postId,
      postContent: item.json.postContent,
      postTitle: item.json.postTitle || '',
      photos: [],
      sourceCount: { unsplash: 0, pexels: 0, pixabay: 0 }
    });
  }

  const data = headingMap.get(key);
  data.photos.push(...photos);
  data.sourceCount[source] = (data.sourceCount[source] || 0) + photos.length;
}

const output = [];

for (const [key, data] of headingMap.entries()) {
  if (data.photos.length > 0) {
    const scored = data.photos
      .map(photo => ({ photo, score: scoreFoodRelevance(photo, data.heading) }))
      .sort((a, b) => b.score - a.score);

    const foodPhotos = scored.filter(s => s.score > 0);
    const topPhotos = (foodPhotos.length > 0 ? foodPhotos : scored).slice(0, 15).map(s => s.photo);

    const sc = data.sourceCount;
    console.log(`${data.heading}: ${data.photos.length} photos (U:${sc.unsplash} P:${sc.pexels} X:${sc.pixabay}), best score ${scored[0].score} from ${scored[0].photo.source} — "${scored[0].photo.alt_description?.slice(0,50)}"`);

    output.push({
      json: {
        heading: data.heading,
        postId: data.postId,
        postContent: data.postContent,
        valid: true,
        results: topPhotos,
        totalFound: data.photos.length
      }
    });
  } else {
    const retryQuery = data.heading.replace(/\s*\([^)]*\)/g, '').split(/\s+/).slice(0, 2).join(' ') + ' food';
    output.push({
      json: {
        heading: data.heading,
        postId: data.postId,
        postContent: data.postContent,
        valid: false,
        results: [],
        totalFound: 0,
        retryQuery
      }
    });
    console.log(`${data.heading}: no photos from any source. Retry: ${retryQuery}`);
  }
}

return output;

// PICK BEST IMAGES — ensure unique images per article (postId)
// using canonical image keys so same photo with different query params is treated as duplicate.

const FOOD_POSITIVE = [
  'food','dish','meal','plate','bowl','soup','cook','kitchen','recipe',
  'eat','dining','cuisine','restaurant','ingredient','flavor','spice',
  'noodle','rice','bread','meat','fish','vegetable','fruit','dessert',
  'breakfast','lunch','dinner','snack','street food','market','chef',
  'broth','stew','curry','salad','pasta','seafood','grill','bake',
  'roast','fry','steam','boil','sauce','garnish','herb','fresh'
];

const FOOD_NEGATIVE = [
  'people','person','man','woman','men','women','portrait','face',
  'street','city','building','architecture','car','road',
  'crowd','tourist','travel','landscape','nature',
  'mountain','beach','temple','church','mosque','flag',
  'worker','labor','sitting','standing','walking','smiling'
];

function normalizeImageKey(url = '') {
  if (!url) return '';
  try {
    const u = new URL(url);
    const p = u.pathname || '';
    // Unsplash: /photo-<id> or /<id>
    const m = p.match(/([A-Za-z0-9_-]{8,})(?:\.[a-z]+)?$/i);
    if (u.hostname.includes('unsplash') && m) return `unsplash:${m[1]}`;
    // Pexels often has the id in path
    if (u.hostname.includes('pexels') && m) return `pexels:${m[1]}`;
    // Pixabay id in filename like .../photo/2022/01/01/12/00/soup-1234567_1280.jpg
    if (u.hostname.includes('pixabay') && m) return `pixabay:${m[1]}`;
    return `${u.hostname}${p}`.toLowerCase();
  } catch {
    return String(url).split('?')[0].toLowerCase();
  }
}

function sourceBoost(source = '') {
  const s = String(source).toLowerCase();
  if (s.includes('pexels')) return 6;
  if (s.includes('pixabay')) return 3;
  if (s.includes('unsplash')) return 0;
  return 0;
}

function scorePhoto(photo, heading) {
  const text = [
    photo.alt_description || '',
    photo.description || '',
    (photo._tags || []).map(t => (typeof t === 'object' ? t.title : t) || '').join(' ')
  ].join(' ').toLowerCase();

  let score = 0;
  for (const w of FOOD_POSITIVE) if (text.includes(w)) score += 3;
  for (const w of FOOD_NEGATIVE) if (text.includes(w)) score -= 5;

  const cleanHeading = (heading || '').replace(/\s*\([^)]*\)/g, '').toLowerCase();
  const stopWords = new Set(['the','a','an','and','or','in','on','at','to','for','of','with','is','are']);
  const keywords = cleanHeading.split(/\W+/).filter(w => w.length > 2 && !stopWords.has(w));
  for (const kw of keywords) if (text.includes(kw)) score += 4;

  if ((photo.width || 1) > (photo.height || 1)) score += 1;
  score += sourceBoost(photo.source || '');
  return score;
}

const allItems = $input.all();
const usedKeysByPost = new Map();
const results = [];

for (const item of allItems) {
  const photos = item.json.results || [];
  const heading = item.json.heading;
  const postId = String(item.json.postId || '');
  const postContent = item.json.postContent;

  if (!postId || photos.length === 0) continue;
  if (!usedKeysByPost.has(postId)) usedKeysByPost.set(postId, new Set());
  const usedKeys = usedKeysByPost.get(postId);

  const scored = photos
    .map(photo => ({ photo, score: scorePhoto(photo, heading), key: normalizeImageKey(photo.imageUrl || '') }))
    .sort((a, b) => b.score - a.score);

  let picked = null;
  for (const c of scored) {
    if (c.key && !usedKeys.has(c.key)) {
      picked = c;
      break;
    }
  }
  if (!picked) picked = scored[0];

  const best = picked.photo;
  if (picked.key) usedKeys.add(picked.key);

  const alternatives = scored
    .filter(s => (s.photo.imageUrl || '') !== (best.imageUrl || ''))
    .slice(0, 10)
    .map(s => ({
      url: s.photo.imageUrl || '',
      alt: s.photo.alt_description || '',
      author: s.photo.authorName || s.photo.source || '',
      source: s.photo.source || '',
      score: s.score
    }));

  results.push({
    json: {
      imageUrl: best.imageUrl || '',
      authorName: best.authorName || best.source || 'Photo',
      authorUrl: best.authorUrl || '#',
      photoSource: best.source || 'Unsplash',
      heading,
      isFallback: false,
      alt_description: best.alt_description || '',
      description: best.description || '',
