    continue;
  }

  let content = content_raw;
  let replacedCount = 0;

  for (const img of images) {
    const heading = img.heading;
    const sourceLabel = img.photoSource || 'Unsplash';
    const credit = 'Photo by ' + img.authorName + ' on ' + sourceLabel;

    const newBlock = '<!-- wp:image {"sizeSlug":"full","linkDestination":"none","align":"center"} -->\n' +
      '<figure class="wp-block-image aligncenter size-full">' +
      '<img src="' + img.imageUrl + '" alt="' + heading + '" />' +
      '<figcaption class="wp-element-caption">' + credit + '</figcaption>' +
      '</figure>\n' +
      '<!-- /wp:image -->';

    const startMarker = '<!-- UNSPLASH:START:' + heading + ' -->';
    const endMarker = '<!-- UNSPLASH:END:' + heading + ' -->';

    const startIdx = content.indexOf(startMarker);
    const endIdx = content.indexOf(endMarker);

    if (startIdx >= 0 && endIdx >= 0) {
      const fullEndIdx = endIdx + endMarker.length;

      let replaceStart = startIdx;
      let replaceEnd = fullEndIdx;

      const beforeStart = content.substring(Math.max(0, startIdx - 50), startIdx);
      const wpHtmlStart = beforeStart.lastIndexOf('<!-- wp:html -->');
      if (wpHtmlStart >= 0) {
        replaceStart = startIdx - (beforeStart.length - wpHtmlStart);
