      const afterEnd = content.substring(fullEndIdx, fullEndIdx + 50);
      const wpHtmlEnd = afterEnd.indexOf('<!-- /wp:html -->');
      if (wpHtmlEnd >= 0) {
        replaceEnd = fullEndIdx + wpHtmlEnd + '<!-- /wp:html -->'.length;
