    [/(stew|stews|braise|tagine|hotpot|pot roast)/, 'stew'],
    [/(noodle|pasta|spaghetti|udon|soba|pad thai|vermicelli)/, 'noodle'],
    [/(rice|biryani|risotto|paella|congee|pilaf)/, 'rice'],
    [/(bread|loaf|baguette|croissant|sourdough|focaccia)/, 'bread'],
