    [/(burger|sandwich|wrap|taco|burrito)/, 'sandwich'],
    [/(cake|dessert|pie|cookie|brownie|chocolate|pudding|ice cream)/, 'dessert'],
    [/(curry|masala|korma|tikka|dal)/, 'curry'],
