for (let i = 0; i < $input.all().length; i++) {
  const responseJson = $input.all()[i].json;
  const queryInfo = queryItems[i]?.json || {};
  const headingKey = queryInfo._headingKey || (queryInfo.postId + '|||' + queryInfo.heading);
  const heading = queryInfo.heading || '';
  const postId = queryInfo.postId || '';
  const postContent = queryInfo.postContent || '';
  const postTitle = queryInfo.postTitle || '';

  const photos = responseJson.hits || [];

  function normalize(raw) {
      if (!raw.webformatURL && !raw.largeImageURL) return null;
      return {
        imageUrl: raw.webformatURL || raw.largeImageURL || '',
        authorName: raw.user || 'Pixabay',
        authorUrl: `https://pixabay.com/users/${raw.user}-${raw.user_id}/`,
        alt_description: raw.tags || '',
        description: raw.tags || '',
        width: raw.imageWidth || raw.webformatWidth || 1,
        height: raw.imageHeight || raw.webformatHeight || 1,
        likes: raw.likes || 0,
        _tags: (raw.tags || '').split(',').map(t => t.trim()),
        source: 'Pixabay'
      };
  }

  const normalized = photos.map(normalize).filter(p => p && p.imageUrl);

  // Output one item per response, carrying all photos + heading key
  results.push({
    json: {
      _headingKey: headingKey,
      heading,
      postId,
      postContent,
      postTitle,
      _source: 'pixabay',
      photos: normalized
    }
  });
}

return results;

